import random


def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C' if history[0][1] == 'C' else 'D'

    opp_defects = 0
    my_defects = 0
    cc = 0
    for me, op in history:
        if op == 'D':
            opp_defects += 1
        if me == 'D':
            my_defects += 1
        elif op == 'C':
            cc += 1

    defect_rate = opp_defects / n
    last_me, last_op = history[-1]

    # Strong detection of unconditional cooperators: harvest with periodic defection
    # only if they have never defected and we've established mutual cooperation.
    if opp_defects == 0:
        if n >= 90:
            return 'D'
        if n >= 20 and n % 4 == 0:
            return 'D'
        return 'C'

    # Immediate retaliation against recent defection (TFT core)
    if last_op == 'D':
        # Check if opponent is a sustained defector -> stay in D
        recent = history[-8:]
        recent_d = 0
        for _, o in recent:
            if o == 'D':
                recent_d += 1
        if recent_d >= 6 or defect_rate > 0.6:
            # Occasional cheap probe to test for recovery
            if rng.random() < 0.04:
                return 'C'
            return 'D'
        # Moderate opponents: retaliate but probe for recovery
        if rng.random() < 0.3:
            return 'C'
        return 'D'

    # Opponent cooperated last round
    if last_op == 'C':
        # Escape mutual defection lock: if we've both been defecting, cooperate
        if last_me == 'D':
            run_dd = 0
            for i in range(n - 1, -1, -1):
                m, o = history[i]
                if m == 'D' and o == 'D':
                    run_dd += 1
                else:
                    break
            if run_dd >= 2:
                return 'C'
            if rng.random() < 0.7:
                return 'C'
            return 'D'

        # Opponent cooperated and we cooperated
        if defect_rate < 0.25:
            if n >= 90:
                return 'D'
            return 'C'
        # Mixed opponent: cooperate but occasionally test
        if rng.random() < 0.85:
            return 'C'
        return 'D'

    return 'C'
